/*
 * A040831  Continued fraction for sqrt(861).
 * https://oeis.org/A040831
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   continued fraction for sqrt(861). a(0)=29. For n>=1, the
 *            sequence is generated by the standard quadratic surd continued
 *            fraction algorithm and repeats with period 16:
 *            2,1,11,14,1,1,2,2,2,1,1,14,11,1,2,58
 * Range:     u8 n <= 80, u16 n <= 80, u32 n <= 80, u64 n <= 80, u128 n <= 80,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    static bool init = false;
    static seq_t a0 = 0;                 /* floor(sqrt(861)) = 29           */
    static seq_t period[32];
    static idx_t period_len = 0;

    if (!init)
    {
        const idx_t D = 861;

        /* ----- compute a0 = floor(sqrt(D)) ----- */
        idx_t lo = 0, hi = D;
        while (lo < hi)
        {
            idx_t mid = (lo + hi + 1) >> 1;
            if (mid * mid <= D)
                lo = mid;
            else
                hi = mid - 1;
        }
        a0 = lo;

        /* ----- compute continued‑fraction period ----- */
        idx_t m = 0, d = 1;
        seq_t a_val = a0;                /* a0 is the initial term          */
        do
        {
            m   = d * (uint64_t)a_val - m;
            d   = (D - m * m) / d;
            a_val = (a0 + m) / d;
            period[period_len++] = a_val;
        } while (a_val != (seq_t)2 * a0);   /* last term of the period is 2*a0 */

        init = true;
    }

    if (n == 0)
        return a0;

    idx_t pos = (n - 1) % period_len;   /* periodic part starts at a(1) */
    return period[pos];
}
